pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

/**
 * @title AINFT Marketplace
 * @dev A combined ERC721 NFT contract and marketplace for AI Agents.
 * This contract allows users to mint unique AI agents as NFTs, list them for sale,
 * and purchase them using the native currency (e.g., ETH).
 * It includes features like a marketplace fee, pausable functionality, and
 * protection against re-entrancy attacks.
 * The contract owner can set the marketplace fee and the recipient address.
 */
contract AINFT is ERC721URIStorage, Ownable, Pausable, ReentrancyGuard {
    using Counters for Counters.Counter;
    Counters.Counter private _tokenIdCounter;

    string private constant NAME = "AI Agent NFT";
    string private constant SYMBOL = "AINFT";

    struct Listing {
        address seller;
        uint256 price;
    }

    // Mapping from token ID to its listing details
    mapping(uint256 => Listing) private _listings;

    // Fee in basis points (e.g., 250 is 2.5%)
    uint256 public marketplaceFeePercent;
    // Address that receives marketplace fees
    address payable public feeRecipient;

    // --- Events ---

    event Listed(
        uint256 indexed tokenId,
        address indexed seller,
        uint256 price
    );
    event Sold(
        uint256 indexed tokenId,
        address indexed seller,
        address indexed buyer,
        uint256 price
    );
    event ListingCancelled(uint256 indexed tokenId);
    event ListingPriceUpdated(uint256 indexed tokenId, uint256 newPrice);

    /**
     * @dev Initializes the contract. The contract owner must call `setFeeRecipient`
     * after deployment for fee collection to work. A default fee of 2.5% is set.
     */
    constructor() ERC721(NAME, SYMBOL) {
        marketplaceFeePercent = 250; // Default 2.5% fee
    }

    // --- Marketplace Functions ---

    /**
     * @dev Lists an AI Agent NFT for sale on the marketplace.
     * @notice The caller must own the token and must have approved the contract
     * to manage the NFT before listing.
     * @param tokenId The ID of the token to list.
     * @param price The selling price in wei.
     */
    function listAgent(uint256 tokenId, uint256 price) public whenNotPaused {
        require(ownerOf(tokenId) == _msgSender(), "AINFT: You do not own this token");
        require(price > 0, "AINFT: Price must be greater than zero");
        require(_listings[tokenId].seller == address(0), "AINFT: Token is already listed");
        require(
            getApproved(tokenId) == address(this) || isApprovedForAll(ownerOf(tokenId), address(this)),
            "AINFT: Contract not approved to transfer token"
        );

        _listings[tokenId] = Listing({seller: _msgSender(), price: price});
        emit Listed(tokenId, _msgSender(), price);
    }

    /**
     * @dev Updates the price of a listed AI Agent.
     * @param tokenId The ID of the token to update.
     * @param newPrice The new selling price in wei.
     */
    function updateListingPrice(uint256 tokenId, uint256 newPrice) public whenNotPaused {
        Listing storage listing = _listings[tokenId];
        require(listing.seller == _msgSender(), "AINFT: You are not the seller");
        require(newPrice > 0, "AINFT: Price must be greater than zero");

        listing.price = newPrice;
        emit ListingPriceUpdated(tokenId, newPrice);
    }

    /**
     * @dev Cancels a listing for an AI Agent.
     * @param tokenId The ID of the token to unlist.
     */
    function cancelListing(uint256 tokenId) public whenNotPaused {
        Listing memory listing = _listings[tokenId];
        require(listing.seller == _msgSender(), "AINFT: You are not the seller");

        delete _listings[tokenId];
        emit ListingCancelled(tokenId);
    }

    /**
     * @dev Buys a listed AI Agent NFT.
     * The sent value must be equal to the token's listing price.
     * @param tokenId The ID of the token to purchase.
     */
    function buyAgent(uint256 tokenId) public payable whenNotPaused nonReentrant {
        Listing memory listing = _listings[tokenId];
        address seller = listing.seller;

        require(seller != address(0), "AINFT: Token is not listed for sale");
        require(listing.price == msg.value, "AINFT: Incorrect payment amount");
        require(seller != _msgSender(), "AINFT: Seller cannot be the buyer");

        // Clear listing before transfers to pass the `_beforeTokenTransfer` check
        delete _listings[tokenId];

        // Pay fee and seller
        uint256 fee = (msg.value * marketplaceFeePercent) / 10000;
        uint256 sellerProceeds = msg.value - fee;

        if (fee > 0 && feeRecipient != address(0)) {
            (bool feeSuccess, ) = feeRecipient.call{value: fee}("");
            require(feeSuccess, "AINFT: Fee transfer failed");
        }

        (bool sellerSuccess, ) = payable(seller).call{value: sellerProceeds}("");
        require(sellerSuccess, "AINFT: Seller payment failed");

        // Transfer NFT to the buyer
        _transfer(seller, _msgSender(), tokenId);

        emit Sold(tokenId, seller, _msgSender(), msg.value);
    }

    // --- Agent Creation ---

    /**
     * @dev Mints a new AI Agent NFT.
     * @param agentOwner The address that will own the new agent NFT.
     * @param tokenURI_ The URI for the new token's metadata.
     * @return The ID of the newly created token.
     */
    function createAgent(address agentOwner, string calldata tokenURI_) public returns (uint256) {
        require(agentOwner != address(0), "AINFT: Mint to the zero address");
        _tokenIdCounter.increment();
        uint256 newTokenId = _tokenIdCounter.current();
        _safeMint(agentOwner, newTokenId);
        _setTokenURI(newTokenId, tokenURI_);
        return newTokenId;
    }

    // --- Admin Functions ---

    /**
     * @dev Pauses all marketplace activity (listing, buying, etc.).
     */
    function pause() public onlyOwner {
        _pause();
    }

    /**
     * @dev Unpauses the marketplace.
     */
    function unpause() public onlyOwner {
        _unpause();
    }

    /**
     * @dev Sets the marketplace fee percentage.
     * @param _feePercent The new fee in basis points (e.g., 250 for 2.5%).
     */
    function setMarketplaceFeePercent(uint256 _feePercent) public onlyOwner {
        require(_feePercent <= 10000, "AINFT: Fee cannot exceed 100%"); // 10000 = 100%
        marketplaceFeePercent = _feePercent;
    }

    /**
     * @dev Sets the address that will receive marketplace fees.
     * @param _recipient The address of the new fee recipient.
     */
    function setFeeRecipient(address payable _recipient) public onlyOwner {
        require(_recipient != address(0), "AINFT: Fee recipient cannot be the zero address");
        feeRecipient = _recipient;
    }

    // --- View Functions ---

    /**
     * @dev Returns the listing details for a given token ID.
     * @param tokenId The ID of the token.
     * @return A Listing struct containing the seller's address and the price.
     */
    function getListing(uint256 tokenId) public view returns (Listing memory) {
        return _listings[tokenId];
    }

    // --- Overrides ---

    /**
     * @dev See {ERC721-_beforeTokenTransfer}.
     * This hook prevents the transfer of a token that is currently listed for sale.
     * The `buyAgent` function works by first deleting the listing, then transferring.
     */
    function _beforeTokenTransfer(address from, address to, uint256 tokenId, uint256 batchSize)
        internal
        whenNotPaused
        override
    {
        super._beforeTokenTransfer(from, to, tokenId, batchSize);

        if (from != address(0)) {
            // The `tokenId` parameter is the first token ID in a batch.
            // This contract's logic assumes single token transfers where batchSize is 1.
            require(batchSize == 1, "AINFT: Batch transfers are not supported for listed tokens");
            require(_listings[tokenId].seller == address(0), "AINFT: Token is listed and cannot be transferred");
        }
    }

    /**
     * @dev See {ERC721-_burn}.
     */
    function _burn(uint256 tokenId) internal override {
        // A listed token cannot be burned due to the _beforeTokenTransfer hook.
        // The owner must cancel the listing first.
        super._burn(tokenId);
    }

    /**
     * @dev See {ERC721URIStorage-tokenURI}.
     */
    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        return super.tokenURI(tokenId);
    }

    /**
     * @dev See {IERC165-supportsInterface}.
     */
    function supportsInterface(bytes4 interfaceId) public view override returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

